def satir_farki(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    if not a and not b:
        return []

    # LCS hesaplama için DP tablosu oluşturuyoruz
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # LCS uzunluğu hesaplanıyor
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Geri izleme ile farkları buluyoruz
    result = []
    i, j = m, n

    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i-1] == b[j-1]:
            result.append((" ", a[i-1]))
            i -= 1
            j -= 1
        elif i > 0 and (j == 0 or dp[i-1][j] > dp[i][j-1]):
            result.append(("-", a[i-1]))
            i -= 1
        else:
            result.append(("+", b[j-1]))
            j -= 1

    # Sonuçları tersine çeviriyoruz, çünkü geriye doğru hesapladık.
    return list(reversed(result))

